import { test, expect } from '@playwright/test';

test.describe('Item Detail View', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/items');
  });

  test('should display item details when clicking on an item', async ({ page }) => {
    // Verify the list of items is visible
    const itemList = page.getByRole('region', { name: /items/i });
    await expect(itemList).toBeVisible();

    // Get the first item using getByRole
    const firstItem = page.getByRole('listitem', { name: /item 1/i });
    await expect(firstItem).toBeVisible();

    // Get the item details button using getByRole
    const detailsButton = page.getByRole('button', { name: /view details/i });
    await expect(detailsButton).toBeVisible();

    // Click the details button to open the modal
    await detailsButton.click();

    // Verify the modal is visible
    const detailsModal = page.getByRole('dialog', { name: /item details/i });
    await expect(detailsModal).toBeVisible();

    // Verify the item details are displayed
    const itemName = page.getByText(/item 1/i);
    await expect(itemName).toBeVisible();

    const itemDescription = page.getByText(/description of item 1/i);
    await expect(itemDescription).toBeVisible();

    const itemPrice = page.getByText(/price: $100/i);
    await expect(itemPrice).toBeVisible();

    // Verify the close button is present
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify the item details modal has a close button
    await expect(detailsModal).toContainText(/close/i);
  });

  test('should handle empty item list and display error message', async ({ page }) => {
    // Verify the item list is empty
    const itemList = page.getByRole('region', { name: /items/i });
    await expect(itemList).toBeEmpty();

    // Verify the error message is visible
    const errorMessage = page.getByText(/no items found/i);
    await expect(errorMessage).toBeVisible();

    // Verify the error message has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify the error message is displayed
    await expect(errorMessage).toBeVisible();
  });
});
